insert into public.testimonios (id, nombre, rol, texto, orden, visible) values ('T0001', 'TKAB', 'Lider', 'Gracias al Nexo Artistico he mejorado como artista, la comunidad me brindo un espacio donde puedo expresarme libremente y mejorar junto a otros artistas que me motivan a superarme constantemente a traves de una competencia sana, y es por eso que constantemente busco el bienestar de la comunidad y de todos los integrantes', 1, true) on conflict (id) do nothing;
insert into public.testimonios (id, nombre, rol, texto, orden, visible) values ('T0002', 'Zack', 'Admin Principal', 'Mi experiencia aca es magnifica, me encanta rodearme de buenos artistas, todos talentosos y muy buenos amigos, el trato que me dieron cuando me uni fue muy bueno y por eso siempre busco como admin actualmente dar lo mismo, mejore mucho desde que estoy en la comunidad, todo gracias a los buenos artistas y compañeros que hay', 2, true) on conflict (id) do nothing;
insert into public.testimonios (id, nombre, rol, texto, orden, visible) values ('T0003', 'D.Rojas', 'Administrador', 'Mi experiencia aca fue interesante, como artista puedo aprender de los demas, enseñarles e incluso hacer amistades, todos muy buenos en lo que hacen, intento', 3, true) on conflict (id) do nothing;
insert into public.testimonios (id, nombre, rol, texto, orden, visible) values ('T0004', 'German', 'Miembro', 'Mi experiencia en el grupo a sido sobre todo emocional, se ayudan mutuamente y te dan consejos de como mejorar tu dibujo o te ayudan a encontrar referencias buenas, sobre todo es genial platicar con otros artistas, me gustaria que siguiera creciendo el grupo y sigamos asi', 4, true) on conflict (id) do nothing;
insert into public.testimonios (id, nombre, rol, texto, orden, visible) values ('T0005', 'Jesus', 'Miembro', 'Mi experiencia ha sido muy buena ya tengo tiempo en este grupo y la verdad de los consejos son demasiado buenos ayudan demasiado y es un buen grupo para darte tips y ayudarte en lo que necesite', 5, true) on conflict (id) do nothing;
insert into public.testimonios (id, nombre, rol, texto, orden, visible) values ('T0006', 'Victor', 'Miembro', 'Mi experiencia aquí fue maravillosa, gracias a personas por ejemplo Joel y Emmanuel, pude mejorar mi conocimiento en el dibujo y agrandar también mi conocimiento en la anatomía, todo gracias a ellos y me gusta estar rodeado a artistas que buscan superarse a si mismo como yo, está fue mi experiencia de mi corto plazo que pase aquí.', 6, true) on conflict (id) do nothing;
insert into public.sobre (id, tipo, titulo, descripcion, icono, orden, visible) values ('S001', 'Historia', 'Nuestra Historia', 'Somos una comunidad de artistas que nació de la mano de Greco Art, quien decidió crear un lugar para que sus fans y amigos artistas pudieran compartir sus dibujos y mejorar juntos a través de diversas temáticas como torneos y VS entre integrantes. Hoy en día es manejada por TkAndresB quien le puso Nexo Artistico, nombre que expone su visión de crear un lugar donde los artistas puedan convivir y mejorar juntos.', null, 1, true) on conflict (id) do nothing;
insert into public.sobre (id, tipo, titulo, descripcion, icono, orden, visible) values ('S002', 'Mision', 'Nuestra Mision', 'Crear un espacio inclusivo donde artistas de todo el mundo puedan compartir, aprender y crecer juntos.', null, 2, true) on conflict (id) do nothing;
insert into public.sobre (id, tipo, titulo, descripcion, icono, orden, visible) values ('S003', 'Vision', 'Nuestra Vision', 'Ser la comunidad artística más vibrante y solidaria de Latam', null, 3, true) on conflict (id) do nothing;
insert into public.sobre (id, tipo, titulo, descripcion, icono, orden, visible) values ('S004', 'Valor', 'Colaboracion', 'Creemos en el poder del trabajo conjunto y el apoyo mutuo para alcanzar metas comunes.', null, 4, true) on conflict (id) do nothing;
insert into public.sobre (id, tipo, titulo, descripcion, icono, orden, visible) values ('S005', 'Valor', 'Respeto', 'Valoramos la diversidad de estilos, niveles y perspectivas de cada miembro de nuestra comunidad.', null, 5, true) on conflict (id) do nothing;
insert into public.sobre (id, tipo, titulo, descripcion, icono, orden, visible) values ('S006', 'Valor', 'Creatividad', 'Fomentamos la expresión artística libre y la exploración de nuevas técnicas y estilos.', null, 6, true) on conflict (id) do nothing;
insert into public.sobre (id, tipo, titulo, descripcion, icono, orden, visible) values ('S007', 'Valor', 'Aprendizaje', 'Promovemos el crecimiento continuo y el intercambio de conocimientos entre artistas.', null, 7, true) on conflict (id) do nothing;
insert into public.sobre (id, tipo, titulo, descripcion, icono, orden, visible) values ('S008', 'Unico', 'Torneos y Competencias', 'Organizamos eventos regulares que desafían la creatividad y fomentan la competencia sana entre miembros.', null, 8, true) on conflict (id) do nothing;
insert into public.sobre (id, tipo, titulo, descripcion, icono, orden, visible) values ('S009', 'Unico', 'Biblioteca de Recursos', 'Compartimos una extensa colección de tutoriales, referencias y materiales educativos para todos los niveles.', null, 9, true) on conflict (id) do nothing;
insert into public.sobre (id, tipo, titulo, descripcion, icono, orden, visible) values ('S010', 'Unico', 'Comunidad Activa', 'Más de 40 miembros activos que participan diariamente, comparten feedback y se apoyan mutuamente.', null, 10, true) on conflict (id) do nothing;
insert into public.sobre (id, tipo, titulo, descripcion, icono, orden, visible) values ('S011', 'Unico', 'Proyectos Colaborativos', 'Facilitamos colaboraciones entre miembros para crear obras conjuntas y proyectos innovadores.', null, 11, true) on conflict (id) do nothing;
